import{_ as e,c as n,o as l,a3 as a}from"./chunks/framework.BusRvirq.js";const S=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"엠파시 제품 가이드","text":"Boon to business by agility.","tagline":"'변화에 최적화된 솔루션', Sync Series로 비즈니스 민첩성(Agility)을 극대화합니다.","actions":[{"text":"시작하기","link":"/syncverse/","type":"primary"},{"text":"모든 제품 보기","link":"#sync-series-제품군","type":"secondary"}]},"head":[["meta",{"name":"keywords","content":"테스트 자동화, 엠파시, Empasy, Sync Series, SyncVerse, SyncInsight, AI 오케스트레이션, 멀티 에이전트, AI 관제, SyncBoot, SyncAdmin, SyncCMS, SyncEta, 마이크로서비스 아키텍처, MSA, 소프트웨어 개발, 솔루션, 디지털 혁신, 비즈니스 민첩성, 개발 플랫폼, 백엔드, 프론트엔드, 콘텐츠 관리 시스템, CMS, AI 테스트, 자동화 테스트, QA, 품질 보증, CI/CD, DevOps, 웹사이트 구축, 시스템 통합, SI, ITO, 맞춤형 솔루션, Java, Vue.js, Vue 3, Vite, TypeScript, Freemarker, Selenium"}],["meta",{"property":"og:title","content":"엠파시 Sync Series: 디지털 혁신을 위한 MSA 기반 솔루션 | 개발, CMS, AI 테스트 자동화"}],["meta",{"property":"og:description","content":"엠파시는 SyncBoot, SyncAdmin, SyncCMS, SyncEta로 구성된 Sync Series를 통해 기업의 디지털 혁신과 비즈니스 민첩성을 극대화합니다. MSA 기반 백엔드, 프론트엔드, CMS, AI 테스트 자동화로 개발 속도를 높이고 품질을 보장하며 유지보수 비용을 절감하세요."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/"}]],"features":[{"icon":"⚡","title":"SyncVerse (AI 오케스트레이션)","details":"분산된 도메인 에이전트들이 표준 MCP로 협업하여 시스템 자율 운영을 수행하는 LLM 네이티브 중앙 제어 플랫폼","link":"/syncverse/","linkText":"SyncVerse 문서 바로가기 →"},{"icon":"🔍","title":"SyncInsight (지능형 관제 & 분석)","details":"에이전트 생태계 데이터를 실시간 수집·분석하고 자연어 질의(NLQ)로 비즈니스 인사이트를 도출하는 관제 센터","link":"/syncinsight/","linkText":"SyncInsight 문서 바로가기 →"},{"icon":"🧪","title":"SyncETA (AI E2E 테스트 자동화)","details":"코드리스 GUI 테스트 및 AI Vision 자가치유 파이프라인으로 무인 CI/CD 회귀 검증을 완결하는 테스트 플랫폼","link":"/synceta/","linkText":"SyncETA 문서 바로가기 →"},{"icon":"🚀","title":"SyncBoot (마이크로서비스 백엔드)","details":"Spring Boot 기반 Clean Architecture & DDD와 AI Schema Studio 로우코드 생성기를 제공하는 개발 플랫폼","link":"/syncboot/","linkText":"SyncBoot 문서 바로가기 →"},{"icon":"🌐","title":"SyncCMS (AI 콘텐츠 관리 시스템)","details":"비전문가도 직관적으로 콘텐츠를 관리하고 Live SDK와 온프레미스 AI 보안을 통해 확장하는 차세대 CMS","link":"/synccms/","linkText":"SyncCMS 문서 바로가기 →"},{"icon":"🕷️","title":"SyncCrawl (적응형 크롤링 & RAG)","details":"웹 구조 변경에 자율 대응하고 실시간 지식 파이프라인을 구축하여 고신뢰 RAG 답변을 제공하는 수집 엔진","link":"/synccrawl/","linkText":"SyncCrawl 문서 바로가기 →"}],"footer":"Copyright © 2026 Empasy Inc. All rights reserved."},"headers":[],"relativePath":"index.md","filePath":"ko/index.md","lastUpdated":1787441310000}`),r={name:"index.md"};function s(i,t,o,g,y,c){return l(),n("div",null,[...t[0]||(t[0]=[a('<h2 id="엠파시-sync-series-문서-바로가기" tabindex="-1">엠파시 Sync Series 문서 바로가기 <a class="header-anchor" href="#엠파시-sync-series-문서-바로가기" aria-label="Permalink to “엠파시 Sync Series 문서 바로가기”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">제품군</th><th style="text-align:left;">주요 역할 및 핵심 가치</th><th style="text-align:left;">문서 링크</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>⚡ SyncVerse</strong></td><td style="text-align:left;">멀티 에이전트 A2A 자율 운영 오케스트레이션 &amp; 관제탑</td><td style="text-align:left;"><a href="/syncverse/">SyncVerse 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🔍 SyncInsight</strong></td><td style="text-align:left;">딥 리서치, 실시간 스트리밍 분석 &amp; NL2SQL 데이터 관제</td><td style="text-align:left;"><a href="/syncinsight/">SyncInsight 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🧪 SyncETA</strong></td><td style="text-align:left;">무인 CI/CD, 웹 자동화 테스트 &amp; AI Vision 자가치유</td><td style="text-align:left;"><a href="/synceta/">SyncETA 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🕷️ SyncCrawl</strong></td><td style="text-align:left;">적응형 자율 크롤링 &amp; RAG 지식 기반 파이프라인</td><td style="text-align:left;"><a href="/synccrawl/">SyncCrawl 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🚀 SyncBoot</strong></td><td style="text-align:left;">Java / Spring Boot 기반 고속 MSA 개발 플랫폼 &amp; 로우코드</td><td style="text-align:left;"><a href="/syncboot/">SyncBoot 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🌐 SyncCMS</strong></td><td style="text-align:left;">직관적인 콘텐츠 관리, Live SDK &amp; 온프레미스 AI 보안 CMS</td><td style="text-align:left;"><a href="/synccms/">SyncCMS 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🖥️ SyncAdmin</strong></td><td style="text-align:left;">Vue 3, Vite &amp; TypeScript 기반 엔터프라이즈 관리 시스템 템플릿</td><td style="text-align:left;"><a href="/syncadmin/">SyncAdmin 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>🔌 SyncAPIM</strong></td><td style="text-align:left;">엔터프라이즈 API 라이프사이클 통합 관리 &amp; 보안 게이트웨이</td><td style="text-align:left;"><a href="/syncapim/">SyncAPIM 시작하기 →</a></td></tr><tr><td style="text-align:left;"><strong>📋 Agile</strong></td><td style="text-align:left;">스크럼반(Scrumban) 기반 엠파시 애자일 개발 방법론</td><td style="text-align:left;"><a href="/agile/">Agile 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>📚 Study &amp; Logs</strong></td><td style="text-align:left;">AI 파인튜닝, RAG 연구 및 개발 디버깅 작업 기록</td><td style="text-align:left;"><a href="/study/">Study</a> · <a href="/logs/">Logs</a></td></tr></tbody></table><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>엠파시(Empasy)는 <strong>&quot;Empathic Synergy (공감 시너지)&quot;</strong>라는 핵심 가치를 바탕으로 빠르게 변화하는 비즈니스 환경에 민첩하게 대응하기 위한 차세대 소프트웨어 및 AI 에이전트 솔루션을 제공하는 기업입니다. 솔루션 기반의 SI(시스템 통합) 및 엔터프라이즈 DX 사업을 선도하며, <strong>&quot;변화에 최적화된 솔루션(Boon to Business by Agility)&quot;</strong>을 최고 가치로 내세우는 <strong>Sync Series</strong> 제품군을 통해 기업의 비즈니스 민첩성과 무인 자율 운영을 지원합니다.</p><hr><h2 id="엠파시의-핵심-가치-및-비전" tabindex="-1">엠파시의 핵심 가치 및 비전 <a class="header-anchor" href="#엠파시의-핵심-가치-및-비전" aria-label="Permalink to “엠파시의 핵심 가치 및 비전”">​</a></h2><p>엠파시의 사명인 <strong>&quot;EmpaSy&quot;</strong>는 깊은 공감과 협업을 통해 탁월한 시너지를 창출하는 <strong>&quot;Empathic Synergy&quot;</strong>를 의미합니다. 이는 고객의 비즈니스 페인포인트를 깊이 이해하고 기술적 동반자로서 공동의 목표를 완벽하게 달성하겠다는 철학을 담고 있습니다.</p><ul><li><strong>Boon to Business by Agility</strong>: 소프트웨어는 현대 비즈니스의 심장이며, 시장 변화에 즉각 대응하기 위해서는 기획부터 배포·운영까지의 전 주기가 민첩하게 연결되어야 합니다.</li><li><strong>살아 있는 소프트웨어 (Living Software)</strong>: 고정된 레거시 시스템을 넘어, 시스템 스스로 상태를 진단하고 코드를 자가 치유(Self-Healing)하며 진화하는 차세대 소프트웨어 생태계를 구축합니다.</li><li><strong>AI DLC (AI Development Life Cycle)</strong>: 멀티 에이전트 간 표준 협업 프로토콜(A2A &amp; MCP)을 기반으로 휴먼 에러를 원천 차단하고 엔지니어링 생산성을 극대화합니다.</li></ul><hr><h2 id="sync-series-제품군" tabindex="-1">Sync Series 제품군 <a class="header-anchor" href="#sync-series-제품군" aria-label="Permalink to “Sync Series 제품군”">​</a></h2><p>엠파시의 Sync Series는 소프트웨어 수명 주기 전반에 걸쳐 속도, 품질, 유연성을 극대화하는 엔터프라이즈 AI 에이전트 및 프레임워크 라인업입니다.</p><h3 id="⚡-syncverse-멀티-에이전트-a2a-자율-오케스트레이션" tabindex="-1">⚡ SyncVerse: 멀티 에이전트 A2A 자율 오케스트레이션 <a class="header-anchor" href="#⚡-syncverse-멀티-에이전트-a2a-자율-오케스트레이션" aria-label="Permalink to “⚡ SyncVerse: 멀티 에이전트 A2A 자율 오케스트레이션”">​</a></h3><ul><li><strong>개요</strong>: 개별 분산 소프트웨어 모듈과 도메인 에이전트들을 표준 MCP 기반으로 통합 제어하는 LLM 네이티브 중앙 관제탑입니다.</li><li><strong>핵심 기능</strong>: 자연어 의도 기반 지능형 라우팅(Intent Routing), Swarm 에이전트 작업 조율, FinOps 토큰 비용 통제, 1-Click HITL(Human-in-the-Loop) 거버넌스.</li><li><strong>도입 효과</strong>: 요구사항 분석부터 자율 코딩, 무인 QA, 배포 및 감사까지 6-Step AI DLC 라이프사이클을 단일 파이프라인으로 자동화합니다.</li></ul><h3 id="🔍-syncinsight-엔터프라이즈-의사결정-인텔리전스-관제" tabindex="-1">🔍 SyncInsight: 엔터프라이즈 의사결정 인텔리전스 &amp; 관제 <a class="header-anchor" href="#🔍-syncinsight-엔터프라이즈-의사결정-인텔리전스-관제" aria-label="Permalink to “🔍 SyncInsight: 엔터프라이즈 의사결정 인텔리전스 &amp; 관제”">​</a></h3><ul><li><strong>개요</strong>: 시스템 내외부 데이터를 실시간 수집·분석하여 비즈니스 의사결정과 장애 선제 대응을 지원하는 AI 관제 플랫폼입니다.</li><li><strong>핵심 기능</strong>: 실시간 분산 데이터 스트리밍 분석, Anomaly Detection(이상 징후 자율 탐지), 자연어 기반 맞춤형 데이터 분석(NL2SQL &amp; NLQ), Context-Aware RAG.</li><li><strong>도입 효과</strong>: 복잡한 SQL 작성이나 대시보드 설계 없이 자연어 질의만으로 비즈니스 인사이트를 도출하고 최적의 실행 액션을 제안받습니다.</li></ul><h3 id="🧪-synceta-vision-llm-기반-e2e-테스트-자동화" tabindex="-1">🧪 SyncETA: Vision-LLM 기반 E2E 테스트 자동화 <a class="header-anchor" href="#🧪-synceta-vision-llm-기반-e2e-테스트-자동화" aria-label="Permalink to “🧪 SyncETA: Vision-LLM 기반 E2E 테스트 자동화”">​</a></h3><ul><li><strong>개요</strong>: 웹 및 모바일 환경에서 DOM 변경에 취약한 기존 스크립트 기반 테스트의 한계를 극복하는 AI 자가복구(Self-Healing) 테스트 플랫폼입니다.</li><li><strong>핵심 기능</strong>: Vision-LLM 화면 요소 시각적 재식별, 엑셀(Excel) 테스트케이스 직결 자동 실행, L1~L5 계층별 심층 품질 검증, CI/CD 무인 회귀 테스트 파이프라인.</li><li><strong>도입 효과</strong>: UI 릴리즈 시 발생하는 셀렉터 장애를 런타임에 98.4% 자가 복구하며, 반복 회귀 테스트 비용을 획기적으로 절감합니다.</li></ul><h3 id="🕷️-synccrawl-적응형-자율-크롤링-rag-지식-파이프라인" tabindex="-1">🕷️ SyncCrawl: 적응형 자율 크롤링 &amp; RAG 지식 파이프라인 <a class="header-anchor" href="#🕷️-synccrawl-적응형-자율-크롤링-rag-지식-파이프라인" aria-label="Permalink to “🕷️ SyncCrawl: 적응형 자율 크롤링 &amp; RAG 지식 파이프라인”">​</a></h3><ul><li><strong>개요</strong>: 웹 페이지의 구조 변경에 능동적으로 적응하여 엔터프라이즈 RAG 파이프라인을 위한 고품질 정형 데이터를 수집하는 엔진입니다.</li><li><strong>핵심 기능</strong>: DOM 구조 변화 자동 보정, 지능형 프록시 순환 및 브라우저 프로파일링(안티봇 우회), 고신뢰 JSON 스키마 자동 추출, 벡터 DB 실시간 동기화.</li><li><strong>도입 효과</strong>: 사이트 개편 시 발생하는 크롤러 오류를 최소화하고 지속 가능한 AI 지식 자산을 구축합니다.</li></ul><h3 id="🚀-syncboot-클라우드-네이티브-java-msa-고속-개발-플랫폼" tabindex="-1">🚀 SyncBoot: 클라우드 네이티브 Java MSA 고속 개발 플랫폼 <a class="header-anchor" href="#🚀-syncboot-클라우드-네이티브-java-msa-고속-개발-플랫폼" aria-label="Permalink to “🚀 SyncBoot: 클라우드 네이티브 Java MSA 고속 개발 플랫폼”">​</a></h3><ul><li><strong>개요</strong>: Spring Boot 기반 Clean Architecture와 Domain-Driven Design(DDD)을 적용한 엔터프라이즈 마이크로서비스 개발 프레임워크입니다.</li><li><strong>핵심 기능</strong>: Schema Studio 로우코드 생성기(DDL, 엔티티, CRUD REST API 자동 생성), Saga 패턴 기반 분산 보상 트랜잭션 관리, Sentinel/Seata/SkyWalking 풀스택 통합.</li><li><strong>도입 효과</strong>: 기초 CRUD 및 권한 관리 구축 공수를 대폭 줄여 비즈니스 핵심 로직 개발에 집중할 수 있는 환경을 제공합니다.</li></ul><h3 id="🌐-synccms-개발-지향형-차세대-콘텐츠-관리-시스템" tabindex="-1">🌐 SyncCMS: 개발 지향형 차세대 콘텐츠 관리 시스템 <a class="header-anchor" href="#🌐-synccms-개발-지향형-차세대-콘텐츠-관리-시스템" aria-label="Permalink to “🌐 SyncCMS: 개발 지향형 차세대 콘텐츠 관리 시스템”">​</a></h3><ul><li><strong>개요</strong>: 마케터와 운영자의 직관적인 콘텐츠 퍼블리싱과 개발자의 무한한 커스텀 확장을 동시에 지원하는 Spring Boot 기반 CMS입니다.</li><li><strong>핵심 기능</strong>: FreeMarker 템플릿 엔진 기반 고속 렌더링, Live SDK 연동, 템플릿 기반 I18n 글로벌 다국어 자동 동기화, 온프레미스 AI 보안 가드레일.</li><li><strong>도입 효과</strong>: 벤더 종속성을 탈피하여 엔터프라이즈 요구사항에 맞춘 유연한 사이트 구축 및 안정적인 대규모 트래픽 처리를 보장합니다.</li></ul><h3 id="🖥️-syncadmin-엔터프라이즈-백오피스-ui-템플릿" tabindex="-1">🖥️ SyncAdmin: 엔터프라이즈 백오피스 UI 템플릿 <a class="header-anchor" href="#🖥️-syncadmin-엔터프라이즈-백오피스-ui-템플릿" aria-label="Permalink to “🖥️ SyncAdmin: 엔터프라이즈 백오피스 UI 템플릿”">​</a></h3><ul><li><strong>개요</strong>: Vue 3, Vite, TypeScript 기반으로 설계된 모던 엔터프라이즈 관리자 대시보드 프레임워크입니다.</li><li><strong>핵심 기능</strong>: 역할 기반 동적 라우팅 및 버튼 단위 세분화 권한 제어, Ant Design Vue 호환, Pnpm/TurboRepo 모노레포 아키텍처, Nitro 기반 고성능 Mock 환경.</li></ul><h3 id="🔌-syncapim-엔터프라이즈-api-라이프사이클-게이트웨이" tabindex="-1">🔌 SyncAPIM: 엔터프라이즈 API 라이프사이클 게이트웨이 <a class="header-anchor" href="#🔌-syncapim-엔터프라이즈-api-라이프사이클-게이트웨이" aria-label="Permalink to “🔌 SyncAPIM: 엔터프라이즈 API 라이프사이클 게이트웨이”">​</a></h3><ul><li><strong>개요</strong>: 대규모 트래픽 환경에서 API 보안, 라우팅, 모니터링, 과금을 통합 관리하는 API 게이트웨이 솔루션입니다.</li><li><strong>핵심 기능</strong>: OAuth 2.0 / JWT 기반 다층 보안, 실시간 트래픽 쓰로틀링(Rate Limiting), API 준실시간 성능 모니터링 및 개발자 포털.</li></ul><hr><h2 id="🏆-주요-고객-성공-사례-및-정량적-성과-지표" tabindex="-1">🏆 주요 고객 성공 사례 및 정량적 성과 지표 <a class="header-anchor" href="#🏆-주요-고객-성공-사례-및-정량적-성과-지표" aria-label="Permalink to “🏆 주요 고객 성공 사례 및 정량적 성과 지표”">​</a></h2><p>엠파시는 대기업, 금융, 교육, 공공 등 다양한 산업군의 핵심 비즈니스 시스템에 Sync Series를 성공적으로 적용하여 탁월한 정량적 성과를 입증했습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">고객사 및 프로젝트</th><th style="text-align:left;">적용 솔루션</th><th style="text-align:left;">핵심 정량 성과 및 지표</th><th style="text-align:left;">비즈니스 혁신 가치</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>비상교육 AIDT</strong></td><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;">• <strong>테스트 작성 생산성 80% 향상</strong> (기존 Appium 4시간 ➔ 자연어 기반 0.8시간)<br>• <strong>회귀 테스트 100% 자동화</strong>로 운영 효율 30% 향상<br>• 리팩토링 시 <strong>회귀 장애 0건 (Regression Zero)</strong> &amp; 장애율 0.1% 이하 유지<br>• <strong>OS 동시 실행 성공률 95%</strong>, UI 파편화 검출 정확도 90% 달성</td><td style="text-align:left;">대규모 코드 변경에도 휴먼 에러를 원천 차단하고 상시 무결점 서비스 품질 확보</td></tr><tr><td style="text-align:left;"><strong>홈플러스 &amp; SK매직</strong><br>(MIS 재구축 &amp; BO 개편)</td><td style="text-align:left;"><strong>SyncBoot</strong></td><td style="text-align:left;">• <strong>신규 기능 배포 속도 2배 이상 향상</strong> (월 단위 ➔ 주/일 단위 릴리즈 전환)<br>• 표준 플랫폼 기반 개발 공수 및 현대화 비용 <strong>최대 20% 절감</strong><br>• 학사 및 관리 업무 프로세스 중복 <strong>30% 이상 절감</strong><br>• 380개 현행 테이블 중 실사용 230개(60%) 사전 분석/클렌징 완료</td><td style="text-align:left;">마이크로서비스 전환 및 복합 데이터 마이그레이션 리스크 해소</td></tr><tr><td style="text-align:left;"><strong>LX하우시스 &amp; 천재교육</strong><br>(글로벌 포털 &amp; T셀파)</td><td style="text-align:left;"><strong>SyncCMS</strong></td><td style="text-align:left;">• <strong>글로벌 다국어 사이트 단일 플랫폼 통합</strong> (해외 법인별 독립 사이트 신속 개설)<br>• 템플릿 I18n 엔진으로 <strong>신규 국가 사이트 오픈 기간 획기적 단축</strong><br>• 일일 수백만 PV 및 수십만 교육 콘텐츠 트래픽 상황에서 <strong>무중단 안정성 달성</strong></td><td style="text-align:left;">벤더 종속 없는 유연한 커스터마이징 및 대규모 트래픽 안정 운영</td></tr><tr><td style="text-align:left;"><strong>LG전자 &amp; 현대자동차</strong></td><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;">• 엔터프라이즈 B2B 포털 UI 검증 및 분산 환경 로그 수집 자동화</td><td style="text-align:left;">무인 CI/CD 회귀 검증 체계 구축</td></tr><tr><td style="text-align:left;"><strong>펜타시큐리티</strong></td><td style="text-align:left;"><strong>SyncAPIM</strong></td><td style="text-align:left;">• 대규모 보안 API 라이프사이클 관리 및 고가용성 게이트웨이 구축</td><td style="text-align:left;">API 보안 거버넌스 확립</td></tr></tbody></table><hr><h2 id="결론-비즈니스-민첩성을-위한-신뢰할-수-있는-파트너" tabindex="-1">결론: 비즈니스 민첩성을 위한 신뢰할 수 있는 파트너 <a class="header-anchor" href="#결론-비즈니스-민첩성을-위한-신뢰할-수-있는-파트너" aria-label="Permalink to “결론: 비즈니스 민첩성을 위한 신뢰할 수 있는 파트너”">​</a></h2><p>엠파시의 <strong>Sync Series</strong>는 단순한 독립 도구의 나열이 아닌, <strong>&quot;소프트웨어 전 생애주기(AI DLC)의 자율 운영&quot;</strong>이라는 뚜렷한 아키텍처 철학 위에 구축되었습니다. 검증된 엔지니어링 역량과 정량적으로 입증된 프로젝트 구축 성과를 바탕으로, 급변하는 디지털 환경에서 고객사의 비즈니스 민첩성과 기술 경쟁력을 완벽하게 보장합니다.</p>',34)])])}const h=e(r,[["render",s]]);export{S as __pageData,h as default};
